style.css:
@-moz-document domain("roblox.com") {
body {
    background: #cbdaf1 !important;
    font-family: Verdana, sans-serif !important;
  }

  /* Navigation bar */
  #navigation, .navbar, .rbx-navbar, .nav-menu {
    background-color: #0055bb !important;
    color: white !important;
    border-bottom: 2px solid #003366 !important;
  }

  .navbar a, .rbx-navbar a {
    color: white !important;
  }

  /* Old style buttons */
  button, .btn-primary {
    background-color: #0055bb !important;
    border: 1px solid #003366 !important;
    color: white !important;
    font-weight: bold !important;
  }

  button:hover, .btn-primary:hover {
    background-color: #003366 !important;
  }

  /* Content area */
  .content, .container-main {
    background-color: white !important;
    border: 1px solid #aaa !important;
    padding: 10px !important;
    box-shadow: 0 0 10px rgba(0,0,0,0.1)

  }

  /* Classic logo vibe */
  .navbar-brand img,
  .rbx-logo {
    content: url('https://upload.wikimedia.org/wikipedia/en/4/45/Roblox_2012_logo.png') !important;
    height: 40px !important;
    image-rendering: pixelated !important;
  }

  /* Remove modern overlays & ads */
  .modern-overlay, .cookie-banner, .promo-banner, .ad, .ads-container {
    display: none !important;
  }
}
